# File is 67KB - might have encoding issues. Let me try a different approach
python3 -c "
import json
count = 0
with open('.state/sessions/history/s_1774015819274_60/session.jsonl', 'r') as f:
    for line in f:
        line = line.strip()
        if not line: continue
        try:
            msg = json.loads(line)
            if msg.get('role') == 'assistant':
                count += 1
                content = msg.get('content', [])
                for part in content:
                    if isinstance(part, dict) and part.get('type') == 'text':
                        txt = part.get('text', '')
                        if txt.strip():
                            print(f'[MSG {count}] {txt[:300]}')
                            print('===')
        except json.JSONDecodeError:
            pass
