import json
with open('.state/sessions/history/s_1774015769660_59/session.jsonl', 'r') as f:
    for i, line in enumerate(f):
        if i < 55 or i > 70:
            continue
        line = line.strip()
        if not line: continue
        try:
            msg = json.loads(line)
            role = msg.get('role')
            if role == 'toolResult':
                content = msg.get('content', [])
                txt = ''
                if isinstance(content, list):
                    for p in content:
                        if isinstance(p, dict) and p.get('type') == 'text':
                            txt += p.get('text', '')
                elif isinstance(content, str):
                    txt = content
                # Just show first 400 chars
                print(f'[L{i} toolResult] {txt[:400]}')
                print('===')
            elif role == 'assistant':
                content = msg.get('content', [])
                if isinstance(content, list):
                    for p in content:
                        if isinstance(p, dict):
                            if p.get('type') == 'toolCall':
                                print(f'[L{i} toolCall] {p.get("name","?")}({str(p.get("arguments",""))[:200]})')
                            elif p.get('type') == 'text' and p.get('text','').strip():
                                print(f'[L{i} text] {p["text"][:300]}')
        except:
            pass
PYEOF

